from pathlib import Path
import pymupdf as fitz,html,json
BASE=Path(__file__).resolve().parent
D=fitz.open(BASE/'assets/base_report.pdf');changes=[]
def replace(i,rect,text,size=10):
 p=D[i];r=fitz.Rect(rect)
 p.add_redact_annot(r,fill=(1,1,1));p.apply_redactions(images=0,graphics=0)
 spare,scale=p.insert_htmlbox(r,html.escape(text).replace('\n','<br>'),css=f'* {{font-family: serif;font-size:{size}pt;line-height:1.12;}}',scale_low=0.9)
 if spare<0:raise ValueError((i,text))
 changes.append({'page':i+1,'rect':list(r),'text':text,'scale':scale})
